// ─── modelos/api-libros.js ───────────────────────────────────────────────────────────────────
// Acceso a la API de libros del backend y la regla de importación (la misma que aplica la web).

/**
 * Cliente de la API. `httpRequest` es la función de n8n (`this.helpers.httpRequest`); en las
 * pruebas se sustituye por una falsa.
 */
function apiLibros(httpRequest, apiUrl) {
  const base = apiUrl.replace(/\/+$/, '');
  const llamar = async (method, ruta, opciones = {}) => {
    const r = await httpRequest({
      method, url: `${base}${ruta}`, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, ...opciones,
    });
    if (r.statusCode >= 400) {
      const cuerpo = r.body ?? {};
      const campos = cuerpo.fields ? Object.values(cuerpo.fields).join('; ') : '';
      throw new Error(campos || cuerpo.message || `La API respondió ${r.statusCode}`);
    }
    return r.body;
  };
  return {
    /** GET /books/duplicates → { sameBook, differentGenre } */
    buscarDuplicado: (libro) => llamar('GET', '/books/duplicates', { qs: libro }),
    /** POST /books/{id}/copies → libro actualizado */
    sumarEjemplares: (id, cantidad) => llamar('POST', `/books/${id}/copies`, { body: { quantity: cantidad } }),
    /** POST /books → libro creado */
    crear: (libro, ejemplares) => llamar('POST', '/books', { body: { ...libro, totalCopies: ejemplares } }),
  };
}

/**
 * Registra un libro: si ya existe (mismo título, autor y género) le suma los ejemplares;
 * si no, lo crea, avisando si había uno igual con otro género.
 * @returns {{ accion: 'sumado', totalCopies } | { accion: 'creado', otrosGeneros: string[] }}
 */
async function registrarLibro(api, libro, ejemplares) {
  const duplicado = await api.buscarDuplicado(libro);
  if (duplicado.sameBook) {
    const actualizado = await api.sumarEjemplares(duplicado.sameBook.id, ejemplares);
    return { accion: 'sumado', totalCopies: actualizado.totalCopies };
  }
  await api.crear(libro, ejemplares);
  return { accion: 'creado', otrosGeneros: (duplicado.differentGenre ?? []).map((l) => l.genre) };
}

// ─── modelos/csv-libros.js ───────────────────────────────────────────────────────────────────
// Lectura del CSV de libros: separador, comillas, cabeceras con alias y validación de cada fila.

/** Columnas reconocidas y sus nombres alternativos (sin tildes ni mayúsculas). */
const ALIAS_COLUMNAS = {
  title: ['titulo', 'title', 'libro'],
  author: ['autor', 'autora', 'author'],
  genre: ['genero', 'genre', 'categoria'],
  copies: ['ejemplares', 'copias', 'cantidad', 'unidades', 'copies', 'totalcopies'],
};
const OBLIGATORIAS = { title: 'titulo', author: 'autor', genre: 'genero' };

/** Excel en español guarda los CSV con «;»; el resto, con «,». Se decide por la cabecera. */
function detectarSeparador(texto) {
  const primeraLinea = texto.split(/\r?\n/, 1)[0];
  const cuenta = (c) => primeraLinea.split(c).length - 1;
  return cuenta(';') > cuenta(',') ? ';' : ',';
}

/** Convierte el texto en filas de celdas, respetando comillas («"a, b"» y «""» dentro). */
function filasCsv(texto, separador) {
  const filas = [];
  let fila = [], valor = '', entreComillas = false;
  for (let i = 0; i < texto.length; i++) {
    const c = texto[i];
    if (entreComillas) {
      if (c === '"' && texto[i + 1] === '"') { valor += '"'; i++; }
      else if (c === '"') entreComillas = false;
      else valor += c;
    } else if (c === '"') entreComillas = true;
    else if (c === separador) { fila.push(valor); valor = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && texto[i + 1] === '\n') i++;
      fila.push(valor); filas.push(fila); fila = []; valor = '';
    } else valor += c;
  }
  if (valor !== '' || fila.length) { fila.push(valor); filas.push(fila); }
  return filas;
}

const normalizar = (s) => s.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]/g, '');

/** Posición de cada columna conocida y las obligatorias que faltan. */
function columnasCsv(cabecera) {
  const posicion = {};
  cabecera.forEach((nombre, i) => {
    const n = normalizar(nombre);
    for (const [clave, alias] of Object.entries(ALIAS_COLUMNAS)) {
      if (alias.includes(n) && posicion[clave] === undefined) posicion[clave] = i;
    }
  });
  const faltan = Object.keys(OBLIGATORIAS).filter((c) => posicion[c] === undefined).map((c) => OBLIGATORIAS[c]);
  return { posicion, faltan };
}

/**
 * Lee el CSV completo.
 * @returns {{ separador, cabecera: string[], faltan: string[], filas: { numero, libro, ejemplares, textoEjemplares }[] }}
 *   `numero` es la fila tal como la cuenta una hoja de cálculo (la cabecera es la 1). Las filas vacías se omiten.
 */
function leerCsvLibros(texto) {
  const limpio = texto.replace(/^\uFEFF/, '');
  const separador = detectarSeparador(limpio);
  const [cabecera = [], ...resto] = filasCsv(limpio, separador);
  const { posicion, faltan } = columnasCsv(cabecera);
  const filas = [];
  resto.forEach((celdas, i) => {
    const celda = (clave) => (posicion[clave] === undefined ? '' : (celdas[posicion[clave]] ?? '').trim());
    const libro = { title: celda('title'), author: celda('author'), genre: celda('genre') };
    if (!libro.title && !libro.author && !libro.genre) return;
    const textoEjemplares = celda('copies');
    filas.push({ numero: i + 2, libro, textoEjemplares, ejemplares: textoEjemplares === '' ? 1 : Number(textoEjemplares) });
  });
  return { separador, cabecera, faltan, filas };
}

/** Error de la fila antes de llamar a la API, o null si se puede enviar. */
function validarFila({ libro, ejemplares, textoEjemplares }) {
  if (!Number.isInteger(ejemplares) || ejemplares < 1 || ejemplares > 1000) {
    return `«${textoEjemplares}» no es un número de ejemplares válido (de 1 a 1000)`;
  }
  if (!libro.title || !libro.author || !libro.genre) return 'faltan el título, el autor o el género';
  return null;
}

// ─── modelos/importacion.js ──────────────────────────────────────────────────────────────────
// Proceso de importación: recorre las filas del CSV en orden y registra cada libro.
// Un libro repetido dentro del mismo CSV se crea una vez y luego se le suman los ejemplares.

/**
 * @param filas resultado de `leerCsvLibros(...).filas`
 * @param api   cliente de `apiLibros(...)` (o uno falso en las pruebas)
 * @returns {Promise<{ resultados: object[], creados, actualizados, errores }>}
 *   Cada resultado: { numero, titulo, ejemplares } más { accion: 'creado', otrosGeneros },
 *   { accion: 'sumado', totalCopies } o { accion: 'error', error }.
 */
async function importarFilas(filas, api) {
  const resultados = [];
  for (const fila of filas) {
    const base = { numero: fila.numero, titulo: fila.libro.title, ejemplares: fila.ejemplares };
    const invalida = validarFila(fila);
    if (invalida) {
      resultados.push({ ...base, accion: 'error', error: invalida });
      continue;
    }
    try {
      resultados.push({ ...base, ...(await registrarLibro(api, fila.libro, fila.ejemplares)) });
    } catch (e) {
      resultados.push({ ...base, accion: 'error', error: e.message });
    }
  }
  const cuenta = (accion) => resultados.filter((r) => r.accion === accion).length;
  return { resultados, creados: cuenta('creado'), actualizados: cuenta('sumado'), errores: cuenta('error') };
}

// ─── modelos/formato.js ──────────────────────────────────────────────────────────────────────
// Fechas y textos que comparten todos los flujos. Las fechas viajan como texto ISO
// (AAAA-MM-DD o fecha y hora con zona) para que las funciones sean fáciles de probar.

/** 2026-10-07 → «07/10/2026». */
const fecha = (iso) => DateTime.fromISO(iso).toFormat('dd/MM/yyyy');

/** 2026-10-07 → «7 de oct». */
const fechaCorta = (iso) => DateTime.fromISO(iso).setLocale('es').toFormat("d 'de' LLL");

/** Fecha y hora conservando la zona horaria con la que se guardó: «13/10/2026 a las 10:56». */
const fechaHora = (iso) => DateTime.fromISO(iso, { setZone: true }).setLocale('es').toFormat("dd/MM/yyyy 'a las' HH:mm");

/** Días enteros entre dos fechas ISO (negativo si `hasta` es anterior). */
const diasEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'days').days);

/** Suma (o resta) días a una fecha ISO. */
const sumarDias = (iso, dias) => DateTime.fromISO(iso).plus({ days: dias }).toISODate();

/** Minutos enteros entre dos instantes ISO. */
const minutosEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'minutes').minutes);

/** «2026-05» → «Mayo 2026». */
const mes = (aaaaMm) => mayuscula(DateTime.fromISO(`${aaaaMm}-01`).setLocale('es').toFormat('LLLL yyyy'));

/** «Del 7 al 13 de octubre de 2026» o «Del 30 de septiembre al 6 de octubre de 2026». */
function rangoFechas(inicioIso, finIso) {
  const a = DateTime.fromISO(inicioIso).setLocale('es');
  const b = DateTime.fromISO(finIso).setLocale('es');
  const inicio = a.month === b.month && a.year === b.year ? a.toFormat('d')
    : a.year === b.year ? a.toFormat("d 'de' LLLL")
      : a.toFormat("d 'de' LLLL 'de' yyyy");
  return `Del ${inicio} al ${b.toFormat("d 'de' LLLL 'de' yyyy")}`;
}

/** 0 → «hoy», 1 → «mañana», 3 → «en 3 días». */
const cuando = (dias) => (dias === 0 ? 'hoy' : dias === 1 ? 'mañana' : `en ${dias} días`);

/** 1 → «ayer», 6 → «hace 6 días». */
const hace = (dias) => (dias === 1 ? 'ayer' : `hace ${dias} días`);

/** 1 → «1 préstamo», 3 → «3 préstamos». */
const plural = (n, uno, varios) => `${n} ${n === 1 ? uno : varios}`;

/** Primera letra en mayúscula. */
const mayuscula = (s) => s[0].toUpperCase() + s.slice(1);

/** 75 → «1 h 15 min», 1 → «1 minuto». */
const duracion = (minutos) => (minutos < 60
  ? plural(minutos, 'minuto', 'minutos')
  : `${Math.floor(minutos / 60)} h ${minutos % 60} min`);

// ─── vistas/html.js ──────────────────────────────────────────────────────────────────────────
// Utilidades HTML comunes a todas las vistas.

/** Escapa un texto para insertarlo en HTML (nombres y títulos vienen de la base de datos). */
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// ─── vistas/pagina-importacion.js ────────────────────────────────────────────────────────────
// Vista del resultado de la importación: la página que ve quien sube el CSV.
// n8n la inserta dentro de su propia página de cierre, así que es un fragmento con estilos en línea.

const COLOR_LINEA = { ok: '#1f2937', nota: '#92400e', error: '#b91c1c' };

/** Texto de cada fila importada. */
function lineaResultado(r) {
  if (r.accion === 'error') return { tipo: 'error', texto: `Fila ${r.numero}: ERROR en «${r.titulo || '(sin título)'}»: ${r.error}` };
  if (r.accion === 'sumado') {
    const sumados = r.ejemplares === 1 ? 'se sumó 1 ejemplar' : `se sumaron ${r.ejemplares} ejemplares`;
    return { tipo: 'ok', texto: `Fila ${r.numero}: «${r.titulo}» ya existía; ${sumados} (ahora tiene ${r.totalCopies}).` };
  }
  const nota = r.otrosGeneros.length ? ` Ojo: ya existía con otro género (${r.otrosGeneros.join(', ')}).` : '';
  return {
    tipo: nota ? 'nota' : 'ok',
    texto: `Fila ${r.numero}: «${r.titulo}» creado con ${plural(r.ejemplares, 'ejemplar', 'ejemplares')}.${nota}`,
  };
}

/** Página con un resumen y una línea por fila. */
function pagina(resumen, lineas) {
  return `<div style="padding:24px 16px">
<div style="max-width:640px;margin:0 auto;background:#fff;border:1px solid #dbdfe7;border-radius:8px;padding:24px;font-size:14px">
<h1 style="font-size:20px;font-weight:600;margin:0 0 8px;color:#1f2937">Importación terminada</h1>
<p style="font-size:15px;margin:0 0 16px;color:#1e3a8a"><strong>${esc(resumen)}</strong></p>
<ul style="padding-left:18px;margin:0">${lineas.map((l) => `<li style="margin:6px 0;color:${COLOR_LINEA[l.tipo]}">${esc(l.texto)}</li>`).join('')}</ul>
<p style="margin:20px 0 0"><a href="/form/importar-libros" style="color:#1e3a8a">Importar otro archivo</a></p>
</div></div>`;
}

/**
 * Resultado de una importación completa.
 * @param importacion resultado de `importarFilas` (modelos/importacion.js)
 * @returns {{ resumen, detalle, pagina }}
 */
function paginaImportacion({ resultados, creados, actualizados, errores }) {
  const lineas = resultados.map(lineaResultado);
  const resumen = lineas.length
    ? [plural(creados, 'libro nuevo', 'libros nuevos'), `${actualizados} con ejemplares sumados`,
      plural(errores, 'fila con error', 'filas con error')].join(' · ')
    : 'El archivo no tiene filas con libros.';
  return { resumen, detalle: lineas.map((l) => l.texto).join('\n'), pagina: pagina(resumen, lineas) };
}

/** El archivo no se puede importar (no llegó o le faltan columnas). */
function paginaErrorArchivo({ faltan, cabecera = [], separador = ',' }) {
  const resumen = faltan
    ? `Al archivo le faltan columnas obligatorias: ${faltan.join(', ')}.`
    : 'No se recibió ningún archivo.';
  const lineas = faltan
    ? [`Cabecera encontrada: ${cabecera.join(' | ') || '(vacía)'}`,
      `La primera fila debe ser: titulo${separador}autor${separador}genero${separador}ejemplares`].map((texto) => ({ tipo: 'error', texto }))
    : [];
  return { resumen, detalle: lineas.map((l) => l.texto).join('\n'), pagina: pagina(resumen, lineas) };
}

// ─── controladores/importar-libros.js ────────────────────────────────────────────────────────
// Nodo «Importar libros» (Importar libros desde CSV): lee el archivo del formulario, registra
// cada fila con las mismas reglas que la web y prepara la página de resultado.

/** @param n8n.helpers funciones de n8n: leer el archivo subido y hacer peticiones HTTP */
async function importarLibros({ $, $input, helpers }) {
  const cfg = $('Configuración').first().json;
  const sinCuentas = { creados: 0, actualizados: 0, errores: 1 };

  const campo = Object.keys($input.first().binary ?? {})[0];
  if (!campo) return [{ json: { ...paginaErrorArchivo({}), ...sinCuentas } }];

  const csv = leerCsvLibros((await helpers.getBinaryDataBuffer(0, campo)).toString('utf8'));
  if (csv.faltan.length) return [{ json: { ...paginaErrorArchivo(csv), ...sinCuentas } }];

  const api = apiLibros((opciones) => helpers.httpRequest(opciones), cfg.apiUrl);
  const importacion = await importarFilas(csv.filas, api);
  const { creados, actualizados, errores } = importacion;
  return [{ json: { ...paginaImportacion(importacion), creados, actualizados, errores } }];
}

return await importarLibros({ $, $input, hoy: $today.toISODate(), ahora: $now.toISO(), memoria: $getWorkflowStaticData('global'), helpers: this.helpers });
